// ---------- the Infinity Castle: entry point for infinitycastle.html ----------
// Fan work after Koyoharu Gotouge's Demon Slayer: Kimetsu no Yaiba (Shueisha, 2016-2020) and ufotable's anime and
// films. Nothing of theirs is used: every shape is generated by castle.js, kit.js and places.js from
// data/cities/infinitycastle.json, and every surface is painted on a canvas when the page opens (mats.js).
//
// What the page is about is the thing the films make of it: a hall so big its walls are lost in haze, with a floor
// of tatami to the horizon, rooms hung from the ceiling, walls of buildings stacked like a city rather than a
// castle, rooms and stairs and bridges every way up in the air between, every one of them lit from inside - and a
// woman with a biwa who can move any of it. So:
//
//   look round     the camera orbits a point; F flies, as in the City
//   the biwa       B, or the button: Nakime strikes it, and the castle reconfigures outward from her - rooms,
//                  districts, walls, the ceiling, the doors (biwa.js). Shift+B, or Biwa ×3, is a great strum.
//                  She plays on her own every fifteen to thirty seconds, and between strums the castle never
//                  quite stops moving, unless you tell her not to
//   fall           the way the Demon Slayer Corps came in: through the doors in the ceiling, down past everything
//                  to the floor, with a line at each thing you pass. #fall in the address starts it
//   the places     Nakime and the stage, the way in and the floor it comes down on, Muzan's lab and his cocoon,
//                  the stair-well, Doma's lake, Akaza's hall, the pillar hall; each is a view and has a card
//
// Like the City, the Backrooms and Kyrene, it brings its own renderer and camera and shares the core modules.
import {report,LOAD,configureLoading,installErrorHandlers,stage,section} from '../core/diag.js';
import {installMenagerie} from '../core/menagerie.js';
import {createWire,installWireUI} from '../core/wire.js';
import {createRenderer,trackResize,installContextLoss,mkBtn as mkBtn0,runHooks,runLoop,finishLoading,boot} from '../core/shell.js';
import {readHash,writeHash as mergeHash} from '../core/hash.js';
import {BIND,FAST,ORBIT_RATE,trackKeys,trackPointers} from '../core/input.js';
import {mkRng} from '../core/rng.js';
import {sceneRows} from '../core/layout.js';
import {makeTextures,makeKitMats,makeFacadeMats} from './mats.js';
import {createKit} from './kit.js';
import {createShell,makeHall,buildCastle} from './castle.js';
import {buildPlaces} from './places.js';
import {createBiwa} from './biwa.js';

installErrorHandlers();window.LOAD=LOAD;
configureLoading({
  lines:[
    'Fan work. Demon Slayer is Koyoharu Gotouge\'s and ufotable\'s; nothing of theirs is used here.',
    'The castle is Nakime\'s Blood Demon Art. It is where she says it is.',
    'ufotable\'s director of photography wanted it Japanese-esque but not Japanese: a Japan designed by someone who has never seen it.',
    'More like a city than a castle: corridors, windows and doorways stacked on top of each other.',
    'Every room keeps its own up. Some of them are on their sides. Some are upside down.',
    'A ken is 1.82 m, the length of one tatami. Everything here is measured in them.',
    'A floor of tatami to the horizon, and rooms hanging from the ceiling over it.',
    'From outside, in the film\'s end credits, the whole castle is one block.',
    'Press B and she plays.',
  ],
  prefix:'the doors are opening… ',labels:{config:'reading the castle',textures:'painting the fusuma',places:'setting out the rooms',castle:'stacking the walls',ui:'tuning the biwa'}});

const ctx=window._iz={};
const getJSON=u=>fetch(u).then(r=>{if(!r.ok)throw new Error(u+': HTTP '+r.status);return r.json();});
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const len=m=>{const a=Math.abs(m);return a<10?m.toFixed(1)+' m':a<1000?Math.round(m)+' m':(m/1000).toFixed(2)+' km';};

async function build(){
  if(!window.THREE){document.getElementById('loading').textContent=
    'three.js did not load (vendor/three/three.min.js). Check the site mounts and reload.';return;}
  const THREE=window.THREE,V3=THREE.Vector3;
  await stage('config');
  const C=await getJSON('data/cities/infinitycastle.json');
  const Q=new URLSearchParams(location.search),HASH=readHash();
  if(+Q.get('seed'))C.seed=+Q.get('seed');
  if(C.seed!==8)document.getElementById('seedtag').textContent='seed '+C.seed;

  // ---- the renderer, the air and the light ----
  const FOG=new THREE.Color(C.fog.color);
  const renderer=createRenderer(THREE,{pixelCap:1.6,clear:FOG});
  installContextLoss(renderer);
  const scene=new THREE.Scene();
  scene.fog=new THREE.FogExp2(FOG.getHex(),C.fog.density);
  // No sun and no sky: what light there is comes out of the rooms, and the haze is lit by it. Warm, and dim.
  scene.add(new THREE.HemisphereLight(0x9a6a44,0x2a1810,0.65));
  const key=new THREE.DirectionalLight(0xffc890,0.28);key.position.set(0.3,1,0.5);scene.add(key);
  const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,0.1,4000);
  const animHooks=[];

  await stage('textures');
  const T=makeTextures(THREE,C.seed,renderer.capabilities.getMaxAnisotropy());
  const mats=makeKitMats(THREE,T),fm=makeFacadeMats(THREE);
  const kit=createKit(THREE,mats,{dotTex:T.dot}),shell=createShell(THREE,fm);
  const root=new THREE.Group();root.name='castle';scene.add(root);
  const hall=makeHall(C),{HALF,CEIL}=hall;

  await stage('places');
  let places=null;
  section('places',()=>{places=buildPlaces({THREE,C,kit,shell,mats,T,root,rnd:mkRng(C.seed*977+3),hall});});
  if(!places)return;
  const A=places.anchors;

  await stage('castle');
  let castle=null;
  section('castle',()=>{castle=buildCastle({THREE,C,kit,shell,rnd:mkRng(C.seed),hall,reserved:places.reserved});});
  if(!castle)return;
  // the floor: tatami, a ken by half a ken, from wall to wall and on under them, lit in pools - under the places,
  // under the lamps of the great floor and the lake, and here and there where some room overhead is lit
  {const t=T.floor.clone();t.needsUpdate=true;const S=2*HALF+240;t.repeat.set(S/1.82,S/1.82);
   const lc=document.createElement('canvas');lc.width=lc.height=512;const g=lc.getContext('2d');
   g.fillStyle='rgb(30,22,14)';g.fillRect(0,0,512,512);
   const px=(x,z)=>[(x/S+0.5)*512,(z/S+0.5)*512];
   const pool=(x,z,r,a)=>{const [u,v]=px(x,z),R=r/S*512,gr=g.createRadialGradient(u,v,0,u,v,R);
     gr.addColorStop(0,`rgba(255,190,110,${a})`);gr.addColorStop(1,'rgba(255,190,110,0)');g.fillStyle=gr;g.fillRect(u-R,v-R,2*R,2*R);};
   const rp=mkRng(C.seed*29+5);
   for(let i=0;i<260;i++)pool((rp()-0.5)*2*HALF,(rp()-0.5)*2*HALF,8+rp()*40,0.12+rp()*0.3);
   const P=C.places;pool(P.floor.x,P.floor.z,P.floor.w*0.8,0.55);pool(P.stage.x,P.stage.z,70,0.5);pool(P.doma.x,P.doma.z,P.doma.r*1.3,0.35);
   const lm=new THREE.CanvasTexture(lc);
   const geo=new THREE.PlaneGeometry(S,S).rotateX(-Math.PI/2);geo.setAttribute('uv2',geo.attributes.uv.clone());
   const floor=new THREE.Mesh(geo,new THREE.MeshLambertMaterial({map:t,color:0x3e3426,lightMap:lm,lightMapIntensity:1.3}));
   floor.userData.kind='tatami';root.add(floor);}
  kit.build(root);shell.build(root);
  // the fingerprint the tests check: everything, as it stands before Nakime first plays
  ctx.lotList=sceneRows(THREE,root);
  ctx.details=Object.assign({seed:C.seed,boxes:shell.boxes.length,kitClusters:kit.clusters.length,lamps:kit.lamps.length},castle.count);

  // light coming down through the haze in shafts, from gaps in the ceiling, the way it slants through every
  // wide shot of the castle: dusty gold, and not a real light, only a glow in the air
  {const c=document.createElement('canvas');c.width=4;c.height=128;const g=c.getContext('2d'),gr=g.createLinearGradient(0,0,0,128);
   gr.addColorStop(0,'rgba(255,255,255,0)');gr.addColorStop(0.08,'rgba(255,255,255,1)');gr.addColorStop(0.5,'rgba(255,255,255,0.45)');gr.addColorStop(1,'rgba(255,255,255,0)');
   g.fillStyle=gr;g.fillRect(0,0,4,128);const tex=new THREE.CanvasTexture(c);
   const rnd=mkRng(C.seed*53+11);
   for(let i=0;i<14;i++){const L=320+rnd()*260,m=new THREE.MeshBasicMaterial({map:tex,color:0xffb060,transparent:true,opacity:0.05+rnd()*0.05,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide});
     const beam=new THREE.Mesh(new THREE.CylinderGeometry(5+rnd()*6,20+rnd()*22,L,20,1,true),m);
     beam.geometry.translate(0,-L/2,0);beam.position.set((rnd()-0.5)*(2*HALF-200),CEIL-4,(rnd()-0.5)*(2*HALF-200));
     beam.rotation.set((rnd()-0.5)*0.7,rnd()*6.3,(rnd()-0.5)*0.7);beam.userData.noFingerprint=true;beam.userData.kind='light shaft';scene.add(beam);}}

  const biwa=createBiwa({THREE,kit,shell,fm,hall,nakime:{pos:A.nakime.pos,arm:A.nakime.fig.arm},reserved:places.reserved});
  animHooks.push(now=>{for(const h of places.hooks)h(now/1000);});

  // ---- the camera: a point you look at, how far away, and from which way ----
  const S={fly:false,flySpeed:12,fall:null,auto:!HASH.has('still')};
  const ctl={t:new V3(),d:40,yaw:0,pitch:0.2,dmin:0.4,dmax:2500};
  const offs=(s,out)=>{const cp=Math.cos(s.pitch);return out.set(s.d*cp*Math.sin(s.yaw),s.d*Math.sin(s.pitch),s.d*cp*Math.cos(s.yaw));};
  const ov3=new V3();
  function place(c,s){c.position.copy(s.t).add(offs(s,ov3));c.lookAt(s.t);}

  // ---- the views ----
  const st=A.stage.pos,nk=A.nakime,dm=A.doma,ak=A.akaza,kk=A.kokushibo,wl=A.well,cc=A.cocoon,lab=A.lab.pos,wi=A.wayin,gf=A.floor.pos;
  const palace=new V3(0,16,dm.pz-12).applyMatrix4(dm.m);
  const VIEWS=[
    {name:'The castle',t:[0,200,0],d:380,yaw:0.72,pitch:0.12,card:'hall'},
    {name:'The floor',t:[80,5,-60],d:24,yaw:0.4,pitch:0.08,card:'tatami'},
    {name:'The ceiling',t:[120,CEIL-40,80],d:300,yaw:2.4,pitch:-1.15,card:'ceiling'},
    {name:'The walls',t:[260,190,-HALF+14],d:110,yaw:0.25,pitch:0.1,card:'walls'},
    {name:'Across the hall',t:[0,280,0],d:170,yaw:1.9,pitch:0.02,card:'hall'},
    {name:'The stage',t:[st.x,st.y+10,st.z],d:78,yaw:0.35,pitch:0.14,card:'stage'},
    {name:'Nakime',t:[nk.pos.x,nk.pos.y-0.1,nk.pos.z],d:3.2,yaw:nk.yaw+0.35,pitch:0.1,card:'nakime'},
    {name:'The way in',t:[wi.x,wi.y,wi.z],d:30,yaw:0.5,pitch:-0.95,card:'wayin'},
    {name:'The great floor',t:[gf.x,1,gf.z],d:150,yaw:-2.4,pitch:0.32,card:'floor'},
    {name:'Muzan\'s lab',t:[lab.x,lab.y-3,lab.z],d:46,yaw:0.4,pitch:-0.38,card:'lab'},
    {name:'The cocoon',t:[cc.pos.x,cc.pos.y+2,cc.pos.z],d:17,yaw:cc.yaw+0.15,pitch:0.08,card:'cocoon'},
    {name:'The stair-well',t:[wl.pos.x,wl.pos.y+wl.H*0.3,wl.pos.z],d:34,yaw:wl.yaw+0.1,pitch:-0.05,card:'well'},
    {name:'Doma\'s lake',t:[palace.x,palace.y,palace.z],d:150,yaw:dm.yaw+0.12,pitch:0.08,card:'doma'},
    {name:'Akaza\'s hall',t:[ak.pos.x,ak.pos.y+1.5,ak.pos.z],d:40,yaw:ak.yaw-0.3,pitch:0.13,card:'akaza'},
    {name:'The pillar hall',t:[kk.pos.x,kk.pos.y+4,kk.pos.z],d:kk.L+6,yaw:kk.yaw,pitch:0.1,card:'kokushibo'},
  ];
  const card=C.cards;

  let anim=null;
  const snap=s=>({t:s.t.clone(),d:s.d,yaw:s.yaw,pitch:s.pitch});
  function setState(s,v){s.t.set(v.t[0],v.t[1],v.t[2]);s.d=v.d;s.yaw=v.yaw;s.pitch=v.pitch;}
  function go(v,T){
    anim=null;const s=ctl,from=snap(s);
    const dl=Math.abs(Math.log(v.d/s.d)),dt=s.t.distanceTo(new V3(...v.t));
    if(T===undefined)T=clamp(1.1+0.3*dl+0.35*Math.log(1+dt/Math.max(v.d,s.d)),1.1,5);
    anim={from,to:v,t0:performance.now(),T:T*1000};
  }
  function step(now){
    const a=anim,s=ctl;const u=clamp((now-a.t0)/a.T,0,1),e=u*u*(3-2*u);
    s.d=Math.exp(Math.log(a.from.d)+(Math.log(a.to.d)-Math.log(a.from.d))*e);
    s.t.set(a.from.t.x+(a.to.t[0]-a.from.t.x)*e,a.from.t.y+(a.to.t[1]-a.from.t.y)*e,a.from.t.z+(a.to.t[2]-a.from.t.z)*e);
    let dy=a.to.yaw-a.from.yaw;dy=Math.atan2(Math.sin(dy),Math.cos(dy));
    s.yaw=a.from.yaw+dy*e;s.pitch=a.from.pitch+(a.to.pitch-a.from.pitch)*e;
    if(u>=1)anim=null;
  }

  // ---- the input ----
  // the site's controls: drag to orbit (flying, to turn the head), right or Shift-drag to pan, the wheel or a
  // pinch to zoom (flying, the wheel is speed); F flies. B is the biwa and M its sound, this page's own
  const el=renderer.domElement;
  const wake=()=>biwa.sound.wake();
  const stopFall=()=>{if(S.fall)endFall();};
  const rv=new V3(),uv=new V3();
  function pan(dx,dy){const s=ctl;const k=2*s.d*Math.tan(camera.fov*Math.PI/360)/innerHeight;
    rv.setFromMatrixColumn(camera.matrix,0);uv.setFromMatrixColumn(camera.matrix,1);
    s.t.addScaledVector(rv,-dx*k).addScaledVector(uv,dy*k);}
  trackPointers(el,{
    down:()=>{wake();stopFall();anim=null;},
    drag:(dx,dy,{pan:p})=>{const s=ctl;
      if(p)pan(dx,dy);
      else if(S.fly){const P0=s.t.clone().add(offs(s,ov3));s.yaw-=dx*0.004;s.pitch=clamp(s.pitch+dy*0.004,-1.52,1.52);s.t.copy(P0).sub(offs(s,ov3));}
      else{s.yaw-=dx*ORBIT_RATE;s.pitch=clamp(s.pitch+dy*ORBIT_RATE,-1.52,1.52);}},
    pinch:(ratio,dx,dy)=>{ctl.d=clamp(ctl.d*ratio,ctl.dmin,ctl.dmax);pan(dx,dy);},
    wheel:(dy)=>{stopFall();anim=null;
      if(S.fly){S.flySpeed=clamp(S.flySpeed*Math.exp(-dy*0.0015),0.5,600);return;}
      ctl.d=clamp(ctl.d*Math.exp(dy*0.0014),ctl.dmin,ctl.dmax);}});
  const keys=trackKeys({onKey:(k,e,held)=>{wake();
    if(held){stopFall();anim=null;return;}
    if(k===BIND.fly){S.fly=!S.fly;syncUI();return;}
    if(k==='b'){play(e.shiftKey?2:1);return;}
    if(k==='m'){toggleSound();return;}
    if(k===BIND.close){views.classList.remove('open');vb.setAttribute('aria-expanded','false');stopFall();}}});

  // ---- the panels ----
  await stage('ui');
  const ui=document.getElementById('ui'),views=document.getElementById('views'),cardEl=document.getElementById('card');
  const mkBtn=(label,parent,fn)=>mkBtn0(label,parent,()=>fn(),{stop:true});
  const vb=mkBtn('Views',ui,()=>{const o=!views.classList.contains('open');views.classList.toggle('open',o);vb.setAttribute('aria-expanded',String(o));
    const m=document.getElementById('menagerie');if(o&&m)m.classList.remove('open');});
  vb.setAttribute('aria-expanded','false');
  let cardTimer=0;
  function showCard(k){const c=k&&card[k];if(!c){cardEl.classList.remove('on');return;}
    cardEl.innerHTML='';const h=document.createElement('h2');h.textContent=c.h;const p=document.createElement('p');p.textContent=c.p;
    const s=document.createElement('p');s.className='sub';s.textContent=c.sub;cardEl.append(h,p,s);cardEl.classList.add('on');
    clearTimeout(cardTimer);cardTimer=setTimeout(()=>cardEl.classList.remove('on'),14000);}
  cardEl.addEventListener('click',()=>cardEl.classList.remove('on'));
  const addGroup=(name,list)=>{const h=document.createElement('div');h.className='sub';h.textContent=name;views.appendChild(h);
    for(const v of list)mkBtn(v.name,views,()=>{stopFall();go(v);showCard(v.card);views.classList.remove('open');vb.setAttribute('aria-expanded','false');});};
  addGroup('The castle',VIEWS.slice(0,5));
  addGroup('Nakime\'s',VIEWS.slice(5,9));
  addGroup('Muzan\'s',VIEWS.slice(9,11));
  addGroup('Where they fight',VIEWS.slice(11));

  const bb=mkBtn('Biwa',ui,()=>play(1));bb.title='Nakime plays, and the castle moves (B)';
  const gb=mkBtn('Biwa ×3',ui,()=>play(2));gb.title='A great strum: three strikes, and the castle turns itself inside out (Shift+B)';
  const ab=mkBtn('',ui,()=>{S.auto=!S.auto;nextAuto=performance.now()+15000;syncUI();writeHash();});ab.title='Whether she plays on her own - every fifteen to thirty seconds, a great strum every fourth time, and the castle never still between';
  const flyB=mkBtn('Fly',ui,()=>{S.fly=!S.fly;syncUI();});flyB.title='Fly (F): drag to look, WASD along where you look, Q/E down and up, the wheel for speed';
  const fallB=mkBtn('Fall',ui,()=>S.fall?endFall():startFall());fallB.title='Fall in through the doors the way the Demon Slayer Corps did, down past everything';
  const sb=mkBtn('',ui,()=>toggleSound());sb.title='The biwa (M)';
  function toggleSound(){wake();biwa.sound.on=!biwa.sound.on;syncUI();}
  function syncUI(){
    flyB.setAttribute('aria-pressed',String(S.fly));
    ab.textContent=S.auto?'Nakime: playing':'Nakime: still';ab.setAttribute('aria-pressed',String(S.auto));
    fallB.textContent=S.fall?'Stop':'Fall';fallB.setAttribute('aria-pressed',String(!!S.fall));
    sb.textContent='Sound: '+(biwa.sound.on?'on':'off');sb.setAttribute('aria-pressed',String(biwa.sound.on));
  }
  const wire=createWire({THREE,scene,animHooks});
  installWireUI({ui,mkBtn,wire,hash:location.hash.slice(1)});
  installMenagerie({ui,mkBtn}).catch(e=>report('menagerie',e));
  const hud=document.createElement('div');hud.id='timebar';document.getElementById('side').appendChild(hud);

  // ---- the biwa ----
  let strumAt=-1e9,moved={rooms:0,blocks:0},nextAuto=performance.now()+15000,autoN=0,nextShift=performance.now()+4000;
  function play(power=1){wake();moved=biwa.strum(camera.position,power);moved.power=power;strumAt=performance.now();}

  // ---- falling in ----
  // From the doors in the ceiling to the floor in half a minute: slow at first, then falling, and a hard stop
  // at the end. The camera turns as it goes and looks down, and each thing it passes gets a line.
  const capEl=document.getElementById('caption');
  const LINES=[
    [CEIL-1,'The doors open','Under the feet of the Demon Slayer Corps the floor turns to sliding doors, and there is nothing under them.'],
    [CEIL-70,'The ceiling','Rooms hang from it like stalactites, the wrong way up, lit through their windows.'],
    [360,'The hall','Walls of buildings on every side, as far as the haze lets you see: a city, not a castle.'],
    [210,'Every way up','Rooms on their sides and upside down, stairs to nowhere, bridges from wall to wall.'],
    [90,'The floor','Tatami to the horizon, and a floor of boards laid on it. In the film, demons are waiting.'],
  ];
  const FT=32000,Y0=CEIL-4,Y1=1.7;
  function startFall(){views.classList.remove('open');cardEl.classList.remove('on');anim=null;S.fly=false;S.fall={t0:performance.now(),line:-1,a0:Math.random()*6.3};syncUI();}
  function endFall(){if(!S.fall)return;
    // leave the camera where it was, orbiting a point a little below it
    const p=camera.position.clone(),dir=new V3();camera.getWorldDirection(dir);ctl.d=30;ctl.t.copy(p).addScaledVector(dir,30);
    ctl.pitch=Math.asin(clamp(-dir.y,-1,1));ctl.yaw=Math.atan2(-dir.x,-dir.z);
    S.fall=null;caption(null);syncUI();}
  function caption(c){if(!c){capEl.classList.remove('on');return;}
    capEl.innerHTML='';const b=document.createElement('b');b.textContent=c[1];const s=document.createElement('span');s.textContent=c[2];
    capEl.append(b,s);capEl.classList.add('on');}
  const lookT=new V3();
  function fallFrame(now){
    const f=S.fall,u=clamp((now-f.t0)/FT,0,1),e=u<0.9?0.94*Math.pow(u/0.9,1.5):0.94+0.06*Math.sin((u-0.9)/0.1*Math.PI/2);
    const y=Y0+(Y1-Y0)*e,a=f.a0+u*2.6,r=6+u*30;
    camera.position.set(wi.x+Math.cos(a)*r,y,wi.z+Math.sin(a)*r);
    // looking down, and out a little as the fall gets going, so the walls go past; level again at the floor
    const land=clamp((u-0.86)/0.14,0,1);
    lookT.set(wi.x+Math.cos(a+0.9)*(r+50*u),y-60+40*u+20*land,wi.z+Math.sin(a+0.9)*(r+50*u));camera.lookAt(lookT);
    let li=-1;for(let i=0;i<LINES.length;i++)if(y<=LINES[i][0])li=i;
    if(li!==f.line){f.line=li;caption(li>=0?LINES[li]:null);f.capAt=now;}
    if(f.capAt&&now-f.capAt>4200)caption(null);
    if(u>=1)endFall();
  }

  // ---- the address ----
  function writeHash(){const s=ctl;
    mergeHash({at:[s.t.x.toFixed(1),s.t.y.toFixed(1),s.t.z.toFixed(1),s.d.toPrecision(4),s.yaw.toFixed(3),s.pitch.toFixed(3)].join(','),
      still:S.auto?null:true,view:null,fall:null,strum:null},['at']);}
  {const at=(HASH.get('at')||'').split(',').map(Number);
   setState(ctl,VIEWS[0]);
   if(at.length===6&&at.every(Number.isFinite))setState(ctl,{t:at.slice(0,3),d:at[3],yaw:at[4],pitch:at[5]});
   const vi=+HASH.get('view');if(HASH.has('view')&&VIEWS[vi]){setState(ctl,VIEWS[vi]);showCard(VIEWS[vi].card);}
   if(HASH.has('fly'))S.fly=true;
   if(HASH.has('fall'))setTimeout(startFall,600);
   // #strum (or #strum=2 for a great strum): she plays as soon as the page is up
   if(HASH.has('strum'))setTimeout(()=>play(+HASH.get('strum')===2?2:1),1500);}
  syncUI();

  trackResize(renderer,camera);
  finishLoading({hintMs:16000,canvas:el});

  // ---- the air: the fog of wherever you are ----
  // Amber haze everywhere; teal over Doma's lake, red round Muzan's lab and in the cocoon's hall, grey-green in
  // the pillar hall. Eased, so crossing from one to the next is not a cut.
  const ZONES=[[new V3(dm.pos.x,20,dm.pos.z),dm.R*1.2,new THREE.Color(0x0b3a44),0.0048],[lab,60,new THREE.Color(0x2a0605),0.0026],
    [cc.pos,16,new THREE.Color(0x1c0708),0.0045],[kk.pos,40,new THREE.Color(0x16201b),0.0035]];
  const fogT=new THREE.Color(),fogC=FOG.clone();let fogD=C.fog.density;

  // ---- the frame ----
  let hashAt=0;
  const PLACES=[['Nakime\'s ledge',nk.pos,8],['the stage',st,40],['the way in',wi,24],['Muzan\'s lab',lab,20],['the cocoon\'s hall',cc.pos,14],
    ['the stair-well',wl.pos.clone().add(new V3(0,wl.H/2,0)),40],['the great floor',new V3(gf.x,10,gf.z),100],['Doma\'s lake',new V3(dm.pos.x,20,dm.pos.z),dm.R+10],
    ['Akaza\'s hall',ak.pos,34],['the pillar hall',kk.pos,38]];
  runLoop((now,dt)=>{
    if(S.fall)fallFrame(now);
    else{
      if(anim)step(now);
      else if(keys.size&&S.fly){const s=ctl,sp=S.flySpeed*(keys.has(BIND.fast)?FAST:1)*dt,f3=offs(s,ov3).normalize().negate();
        const rx=-f3.z,rz=f3.x,rl=Math.hypot(rx,rz)||1;
        if(keys.has('w'))s.t.addScaledVector(f3,sp);if(keys.has('s'))s.t.addScaledVector(f3,-sp);
        if(keys.has('d')){s.t.x+=rx/rl*sp;s.t.z+=rz/rl*sp;}if(keys.has('a')){s.t.x-=rx/rl*sp;s.t.z-=rz/rl*sp;}
        if(keys.has('e'))s.t.y+=sp;if(keys.has('q'))s.t.y-=sp;}
      else if(keys.size){const s=ctl,sp=s.d*0.7*(keys.has(BIND.fast)?FAST:1)*dt;
        const fx=-Math.sin(s.yaw),fz=-Math.cos(s.yaw);
        if(keys.has('w')){s.t.x+=fx*sp;s.t.z+=fz*sp;}if(keys.has('s')){s.t.x-=fx*sp;s.t.z-=fz*sp;}
        if(keys.has('a')){s.t.x+=fz*sp;s.t.z-=fx*sp;}if(keys.has('d')){s.t.x-=fz*sp;s.t.z+=fx*sp;}
        if(keys.has('e'))s.t.y+=sp;if(keys.has('q'))s.t.y-=sp;}
      place(camera,ctl);
    }
    camera.updateMatrixWorld();
    const p=camera.position;
    fogT.copy(FOG);let tgt=C.fog.density;
    for(const [c,r,col,d] of ZONES){const k=clamp(1.6-p.distanceTo(c)/r,0,1);if(k>0){fogT.lerp(col,k);tgt+=(d-tgt)*k;}}
    const k=1-Math.exp(-dt*3);fogC.lerp(fogT,k);fogD+=(tgt-fogD)*k;
    scene.fog.color.copy(fogC);scene.fog.density=fogD;renderer.setClearColor(fogC);
    if(S.auto&&!S.fall&&now>nextAuto){nextAuto=now+14000+Math.random()*14000;play(++autoN%4===0?2:1);}
    // between strums, while she is playing, the castle is never quite still
    if(S.auto&&!S.fall&&now>nextShift){nextShift=now+1000+Math.random()*1500;biwa.restless(camera.position);}
    biwa.update(now,dt,camera.position);
    // the shake of something slamming home near you: a few centimetres to half a metre, and a little roll
    const sh=biwa.shake;if(sh>0.01){const a=sh*Math.min(0.5,0.02*(S.fall?40:ctl.d)+0.08);
      camera.position.x+=(Math.random()-0.5)*a;camera.position.y+=(Math.random()-0.5)*a;camera.position.z+=(Math.random()-0.5)*a;
      camera.rotation.z+=(Math.random()-0.5)*sh*0.02;camera.updateMatrixWorld();}
    runHooks(animHooks,now);
    renderer.render(scene,camera);
    // where you are
    let where=null;for(const [n,c,r] of PLACES)if(p.distanceTo(c)<r){where=n;break;}
    if(!where){const gap=hall.wallGap(p);where=gap<0?'in the walls':gap<20?'at the walls':p.y<4?'on the floor':p.y>CEIL?'in the ceiling':p.y>CEIL-160?'under the ceiling':'in the hall';}
    const ht=len(Math.max(0,p.y))+' up · '+len(Math.max(0,CEIL-p.y))+' under the ceiling';
    const frame=2*(S.fall?40:ctl.d)*Math.tan(camera.fov*Math.PI/360)*camera.aspect;
    const played=now-strumAt<6000?(moved.power>1?'♪♪♪ A great strum: ':'♪ Nakime plays: ')+moved.rooms+' rooms and '+moved.blocks+' blocks move, '+(moved.doors||0)+' rooms slam their doors · ':'';
    hud.textContent=played+(S.fly?'FLYING '+len(S.flySpeed*(keys.has(BIND.fast)?FAST:1))+'/s · ':'')+where.toUpperCase()+' · '+ht+' · frame '+len(frame)+' across';
    if(!S.fall&&now-hashAt>1200){hashAt=now;writeHash();}
  });
  ctx.biwa=biwa;ctx.ctl=ctl;
}

boot(build);
